{"code": "const zlib = await import("node:zlib");
const fs = await import("node:fs");
const path = await import("node:path");
const root = "C:\\Users\\Administrator\\.dsh\\sessions\\--D-lean--";
const dirs = fs.readdirSync(root);
const files: {p:string; size:number; mtime:number}[] = [];
for (const d of dirs) {
  const f = path.join(root, d, "session.v4.jsonl.zstd");
  if (fs.existsSync(f)) { const st = fs.statSync(f); files.push({p:f, size:st.size, mtime:st.mtimeMs}); }
}
files.sort((a,b)=>b.mtime-a.mtime);
const marker = "reducedQPilotAnchor";
const marker2 = "S1960QPilotAnchor";
const hits: any[] = [];
let scanned = 0, bytes = 0;
for (const f of files) {
  if (Date.now()-f.mtime > 8*3600*1000) break;
  let txt = "";
  try {
    const buf = fs.readFileSync(f.p);
    const out = (zlib as any).zstdDecompressSync(buf);
    txt = out.toString("utf8");
  } catch(e) { continue; }
  scanned++; bytes += txt.length;
  if (txt.includes(marker) || txt.includes(marker2)) {
    hits.push({p:f.p, mtime:new Date(f.mtime).toISOString(), size:f.size, dec:txt.length,
      hasMarker: txt.includes(marker), hasMarker2: txt.includes(marker2),
      count: (txt.match(/reducedQPilotAnchor/g)||[]).length});
  }
}
console.log("scanned sessions:", scanned, "decoded chars:", bytes);
console.log("hits:", JSON.stringify(hits, null, 1));
", "description": "Scan recent session transcripts for lost ledger text", "timeoutMs": 300000}

